// src/packs/tempera/temperaStyleNotes.ts
// 凝彩每个镜头风格、族与组件选项的中文名与画面描述（给 AI 编排与 MCP agent 的 list_styles 看）。
// 描述按 compositions/*.ts 的实际绘制与 temperaShotProfiles.ts 的文字区写：画面怎么分割、形状在哪、
// 字排在哪、适合什么段落。改了构图就同步改这里；pack.ts 组装 styles / families / componentSlots 时合进去。
import type { TemperaDecorMotif, TemperaShotKind, TemperaTypography } from './types';

export interface TemperaStyleNote {
    /** 中文显示名。 */
    label: string;
    /** 一两句话的实际画面（25–70 个汉字）。 */
    description: string;
    /** 检索关键词，3–6 个。 */
    keywords: string[];
}

/** 族 id，顺序与数量见 pack.ts 的 FAMILY_SPANS。 */
export type TemperaFamilyId =
    | 'split' | 'band' | 'frame' | 'poster' | 'sparse' | 'cinema' | 'charm'
    | 'aperture' | 'signal' | 'corridor' | 'monolith' | 'terrain' | 'monogatari';

export const TEMPERA_FAMILY_DESCRIPTIONS: Record<TemperaFamilyId, string> = {
    split: '用直线把整幅画面切成几块深浅不同的平涂色块（二分、四分、三栏、斜分、阶梯等），歌词压在分界缝上，跨缝的笔画按底色反色。',
    band: '横向色带与分层：水平色带、上下色轨、由浅到深的渐层与排线密度渐变，配合纵向镜头流向读作一层层往下潜。',
    frame: '线框与窗口（菱形框、圆窗、拱窗、方括号、四角框、九宫格等）把歌词围在一块安静的区域里，多给安静段落用。',
    poster: '一个倾斜或出画的巨大实心形状（菱形、斜带、三角、半圆、叠板）占据画面，歌词压在上面与之对抗，冲击力强，多用于副歌。',
    sparse: '几乎没有色块的稀疏画面：细线、方点点阵、波纹、弧线与手绘涂鸦，歌词小号，适合前奏、间奏与安静段落。',
    cinema: '深色遮幅从四边合拢，中央开一个指定画幅比（2.39、1.85、4:3、1:1、3:4、9:16 或双窗）的窗口，歌词在窗内，电影感。',
    charm: '视觉小说宣传片式的圆润图形：泡泡、云朵框、爱心、四角星、花瓣、花边、缎带、圆角铭牌，铺在平涂底色上，可爱轻快。',
    aperture: '整块色板上挖出真镂空（圆孔、横缝、齿孔、片门、十字孔、百叶等），洞里透出背景画面，歌词始终放在实板上。',
    signal: '仪表盘式的测量装饰（准星、表盘、刻度、网格、条码、放射线）围绕一个重块，歌词与重块共处一框，理性克制。',
    corridor: '沿镜头流向（接近竖直）切出的镂空通道、孔列与车窗，前后镜头的开口接成同一条通道，歌词在旁边的实板上。',
    monolith: '粗野主义巨构：一块被画框裁切的巨大实体（山体、巨墙、悬臂、门架、碉堡等），配贯穿的细测量线与角标，歌词跨在轮廓边缘。',
    terrain: '同一套巨构语汇读作地形与结构：山脊、峡谷、屋檐、阶梯井、栈桥、护坡、塔角、日晷，地平线感更强。',
    monogatari: '物语系列式字卡：整屏纯色、几乎没有几何，也不叠共享点缀，歌词放大成为画面本身，用于停顿、独白与强调。',
};

